parameters.jsCode:
// Deterministic checks first — free, instant, and they catch most of what a reviewer would.
const out = $json.output || $json;
const profile = $('Resolve Channel Spec').first().json.profile || {};
const spec = $('Resolve Channel Spec').first().json.spec || {};
const lex = profile.message?.lexicon || {};
const text = [out.title, out.subtitle, out.body].filter(Boolean).join('\n');
const lower = text.toLowerCase();

const violations = [];
for (const term of (lex.banned || [])) if (lower.includes(term.toLowerCase())) violations.push({ severity: 'block', term });
for (const term of (lex.avoid || [])) if (lower.includes(term.toLowerCase())) violations.push({ severity: 'warn', term });

const words = text.split(/\s+/).filter(Boolean).length;
if (spec.min_words && words < spec.min_words) violations.push({ severity: 'warn', rule: 'below_min_words', words, min: spec.min_words });
if (spec.max_chars && text.length > spec.max_chars) violations.push({ severity: 'block', rule: 'over_max_chars', chars: text.length, max: spec.max_chars });
for (const field of (spec.requires || [])) if (!out[field]) violations.push({ severity: 'block', rule: 'missing_required_field', field });

return [{ json: { ...out, word_count: words, lint: { violations, blocked: violations.some(v => v.severity === 'block') } } }];

// GENERATED epilogue — appends exactly one provenance entry and closes the span.
// Provenance is append-only; nothing in the estate is permitted to rewrite an earlier entry.
const e = $('Envelope In').first().json;
const out = $json;
const duration = Date.now() - (e._started_at ?? Date.now());
const entry = {
  capability: "copy.longform.generate",
  version: "1.0.0",
  at: new Date().toISOString(),
  duration_ms: duration,
  model: out._model ?? null,
  provider: out._provider ?? null,
  cost_minor_units: out._cost_minor_units ?? 6,
  inputs_hash: e.idempotency_key,
  decision_id: out.decision?.decision_id ?? null
};
return [{ json: {
  ...out,
  _envelope: {
    ...e,
    span_id: e.parent_span_id,
    provenance: [...(e.provenance ?? []), entry],
    budget: { ...(e.budget ?? {}), spent_minor_units: (e.budget?.spent_minor_units ?? 0) + (entry.cost_minor_units ?? 0) }
  },
  _telemetry: {
    event_id: 'evt_' + Math.random().toString(36).slice(2, 12),
    trace_id: e.trace_id, span_id: e.span_id, tenant_id: e.tenant_id,
    capability: "copy.longform.generate", capability_version: "1.0.0",
    layer: "terminal", event: 'span_end', status: out.error ? 'error' : 'ok',
    duration_ms: duration, cost_minor_units: entry.cost_minor_units,
    error_code: out.error?.code ?? null, at: new Date().toISOString()
  }
} }];

